-- Migration 419: AA-1051 (S280) — the D12 caps and the minimum samples of the W5 writer proofs in the platform settings
-- registry (CIS 407; tech lead S279: a threshold, limit or cap is a setting on Platform › Settings, never a code
-- literal or an env var alone).
--
-- Why. The W5 writer proofs (root ADR 0020 D12 / W5: the eval null run, then the T9 blog writer, the S1 tour rewrite
-- and the T2 tenant tour writer proofs) are paid runs. Their spend caps (null run 5, T9 15, S1 8, T2 5, 33 USD in
-- total) and the fewest samples a pre-registration may fix (12, 12, 25, 20) are hard-coded today in
-- services/writer_proof/prereg.py (WORKFLOWS, TOTAL_CAP_USD). They are policy, so they live here, with today's values
-- as their defaults.
--
-- What:
--   1. Nine rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR):
--        cis.spend.writer_proof_null_run_cap_usd       usd 0.01..10, default 5,  high,   maker-checker
--        cis.spend.writer_proof_t9_cap_usd             usd 0.01..20, default 15, high,   maker-checker
--        cis.spend.writer_proof_s1_cap_usd             usd 0.01..20, default 8,  high,   maker-checker
--        cis.spend.writer_proof_t2_cap_usd             usd 0.01..20, default 5,  high,   maker-checker
--        cis.spend.writer_proof_total_cap_usd          usd 0.01..50, default 33, high,   maker-checker
--        cis.quality.writer_proof_null_run_min_items   int 5..200,   default 12, medium, maker-checker, evidence
--        cis.quality.writer_proof_t9_min_items         int 5..200,   default 12, medium, maker-checker, evidence
--        cis.quality.writer_proof_s1_min_items         int 5..200,   default 25, medium, maker-checker, evidence
--        cis.quality.writer_proof_t2_min_items         int 5..200,   default 20, medium, maker-checker, evidence
--      (key names spell "writer_proof", not "w5": a short code with digits next to "cap" in the JSON seed tripped the
--      gitleaks generic-api-key rule.)
--      Each seed row carries its plain label and its operator guide (EN + VI: what, raise, lower, when, example), in
--      the guide column CIS 416 added (tests/unit/test_aa1096_settings_guides.py fails a compiled key without one).
--      Seeded with enforced = false (the page badge "not enforced yet"): the code that reads them ships in the next PR
--      of this lane (MIG-4), and the settings-lint guard refuses an enforced key that no code reads. A later migration
--      sets enforced = true once that code is deployed (follow-up in docs/implementation-notes/AA-1051.md).
--      A run's cap can never pass the R2 run cap (10 USD per arm, services/writing_memory/config.R2_RUN_CAP_USD): the
--      runner splits a workflow cap between its arms and clamps each arm there, whatever the setting says.
--   2. Register 419.
--
-- Behaviour on apply. None for running code: no value row is seeded, nothing reads the keys until the proof code is
-- deployed, and then every key resolves to its default (today's literal) until an administrator approves a change.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: a migration-only PR (it joins the wave's CIS migration batch); applied on Dev by Infra Migration Apply when the
-- job tables are idle (ADR 0017a). DM-7.1: no new table.
--
-- Number. 417 is on main; in this wave another lane holds 418 (AA-1077, t9_blog length setting). If the owner main
-- max + 1 differs at merge, renumber (git grep '419_' and '419' here, in tests/integration/test_aa1051_migration_419.py,
-- compiled_defaults.json, tests/unit/test_s279_settings_seed_parity.py and in the code that names the file).
--
-- Locks. One INSERT of nine rows (the definition guard trigger allows the file's role, cis_owner). lock_timeout 5s.
-- Idempotent (ON CONFLICT (key) DO NOTHING), one transaction, self-registering.
--
-- Rollback (a new forward migration, after the proof code is reverted): DELETE the nine keys (no value row can exist
-- before the code reads them; a value row would have to go first).

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$[
{"key": "cis.spend.writer_proof_null_run_cap_usd", "app": "cis", "area": "spend", "label": "Writer proofs: null run spending cap", "description": "Root ADR 0020 D12: the most USD the eval null run (the T9 blog writer, no change) may spend on AI calls, ledger spend plus the caps of its queued or running jobs (shared.llm_call_log, stage adhoc_aa1051). A pre-registration's own cap_usd must be at or below it; each run also needs the tech lead's own yes. Read by the W5 proof runner (services/writer_proof) from the release that ships it; marked enforced by a later migration.", "value_type": "usd", "unit": "USD", "min_value": 0.01, "max_value": 10, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 30, "enforced": false, "guide": {"en": {"what": "The most money, in US dollars, that the null run (the first writer proof: the blog writer re-run with no change, to show the scoring itself is stable) may spend on AI calls in total. A writer proof is a paid test that checks, on a fixed set of samples, whether a change to an AI writer keeps or improves the quality of what it writes. Money already spent and the limits of tests still waiting in the queue both count.", "raise": "A bigger or pricier test fits under the limit, but a test that goes wrong spends more before it is stopped, and less of the overall test budget is left for the other tests.", "lower": "The test stays cheap, but a plan that needs more than the limit is refused before it starts, so the test must use fewer samples or a cheaper checking model.", "when": "Raise it when the dry-run plan shows the pre-registered sample cannot fit and the tech lead agrees to spend more; lower it when the month's AI budget is tight.", "example": "With the default of 5 USD, a null run on 12 blog samples with the default checking model fits with room to spare."}, "vi": {"what": "Số tiền tối đa (đô la Mỹ) mà lần chạy đối chứng (writer proof đầu tiên: chạy lại bước viết blog không thay đổi gì, để chứng minh cách chấm điểm ổn định) được tiêu cho các lượt gọi AI. Writer proof là một bài kiểm tra có tính phí, chạy trên một bộ mẫu cố định, để xem một thay đổi của bước AI viết bài có giữ được hoặc nâng chất lượng bài viết hay không. Cả số tiền đã tiêu lẫn giới hạn của các bài kiểm tra còn đang chờ trong hàng đợi đều được tính.", "raise": "Bài kiểm tra lớn hơn hoặc đắt hơn vẫn nằm trong giới hạn, nhưng nếu bài kiểm tra gặp lỗi thì sẽ tốn nhiều tiền hơn trước khi bị dừng, và phần ngân sách chung còn lại cho các bài kiểm tra khác ít đi.", "lower": "Bài kiểm tra rẻ hơn, nhưng kế hoạch nào cần nhiều hơn giới hạn sẽ bị từ chối trước khi chạy, nên phải dùng ít mẫu hơn hoặc model chấm rẻ hơn.", "when": "Tăng khi bản kế hoạch chạy khô cho thấy bộ mẫu đã đăng ký trước không vừa và tech lead đồng ý chi thêm; giảm khi ngân sách AI của tháng đang eo hẹp.", "example": "Với mặc định 5 USD, một lần chạy đối chứng trên 12 bài blog mẫu với model chấm mặc định vẫn còn dư."}}},
